scripts.source:
// 聚合 CVD。按图表周期累计主动买入减主动卖出（美元），市场范围跟随页面的 ALL VENUES。
// 早期缺少录制时，页面用可用的 Binance K 线回补。未知流量留空，下一根有数据时继续累计。
// 红绿箭头标出价格对净主动成交反应偏弱的区间。只用已经收盘、数据来源一致的连续 K 线。

lineColor = option(type=color, default=#54b6c8, label="CVD 线色")
showMarks = option(type=checkbox, default=true, label="显示价量背离标记")
showBounds = option(type=checkbox, default=true, label="显示标记区间上下沿")
lookback = option(type=number, default=20, min=3, max=200, step=1, label="回看 K 线根数")
minDelta = option(type=number, default=2, min=0.1, max=50, step=0.1, label="最小净主动成交占比 (%)")
maxResponse = option(type=number, default=15, min=0, max=60, step=1, label="最大同向价格位移 (% 区间振幅)")

feed = bar.recorded
var hasFlow = (feed == 1 || feed == 0) && isFinite(vbuy + vsell)
var delta = hasFlow ? vbuy - vsell : NaN
var cvd = cum(delta)
line(cvd, title="聚合 CVD", color=lineColor, lineWidth=2, priceScaleId=cvdUsd)
if (renderer.last) mark(cvd, title="最新 CVD", color=lineColor, shape=tag, priceScaleId=cvdUsd)

if (showMarks) {
  var n = Math.max(3, Math.min(200, Math.round(lookback)))
  starts = time
  opens = $price.open
  var hi = $price.high, lo = $price.low, close = $price.close
  var usable = hasFlow && isFinite(opens) && isFinite(hi) && isFinite(lo) && isFinite(close) && lo > 0 && hi >= lo
  var adjacent = starts - starts[1] == renderer.timeframe
  coveredBars = usable ? (adjacent && feed == feed[1] ? coveredBars + 1 : 1) : 0

  var net = sum(usable ? delta : 0, n)
  var gross = sum(usable ? vbuy + vsell : 0, n)
  var span = highest(usable ? hi : 0, n) - lowest(usable ? lo : 0, n)
  var startOpen = opens[n - 1]
  var move = close - startOpen
  var share = gross > 0 ? 100 * net / gross : 0
  var response = span > 0 ? 100 * Math.sign(net) * move / span : 0
  var upper = highest(cvd, n), lower = lowest(cvd, n)

  // A marked window must close and can share no candles with the previous marked window.
  var clear = lastMarkedBar == 0 || renderer.length - lastMarkedBar >= n
  if (!renderer.forming && coveredBars >= n && clear && Math.abs(share) >= minDelta && response <= maxResponse) {
    lastMarkedBar = renderer.length
    var buysLead = net > 0
    var color = buysLead ? "#69b975" : "#e6584e"
    var tip = (buysLead ? "净主动买入，价格跟涨偏弱" : "净主动卖出，价格跟跌偏弱")
      + " · " + n + " 根 K 线"
      + "\n净主动成交 / 总主动成交：" + share.toFixed(2) + "%"
      + "\n窗口价格变化：" + (100 * move / startOpen).toFixed(2) + "%"
      + "\n数据：" + (feed == 1 ? "页面录制" : "Binance K 线回补")
    if (buysLead) mark(cvd, "", tip, color, title="买盘占优，价格跟涨偏弱", shape=arrowUp, position=below, priceScaleId=cvdUsd)
    else mark(cvd, "", tip, color, title="卖盘占优，价格跟跌偏弱", shape=arrowDown, position=above, priceScaleId=cvdUsd)
    if (showBounds) {
      var from = starts[n - 1]
      level(upper, from, time, "", color, title="区间上沿", lineStyle=2, priceScaleId=cvdUsd)
      level(lower, from, time, "", color, title="区间下沿", lineStyle=2, priceScaleId=cvdUsd)
    }
  }
}
